-- New shelves (2026-10-28): sarees, dress material, co-ord sets, gowns, indo-western,
-- temple and oxidised jewellery, potlis, torans, bandhanwar, with one piece on each.
-- The old rows are saved in supabase/backups/.
delete from public.products where id not in ('temple-border-saree', 'block-print-set', 'printed-coord', 'anarkali-gown', 'pearl-hoops', 'temple-jhumka', 'crescent-chandbali', 'embroidered-potli', 'haveli-toran', 'pompom-swag');

on conflict (slug) do update set no = excluded.no, title = excluded.title, accent = excluded.accent, blurb = excluded.blurb,
  care = excluded.care, feature_product_id = excluded.feature_product_id, sort = excluded.sort, i18n = excluded.i18n;

on conflict (id) do update set category_slug = excluded.category_slug, name = excluded.name, mini = excluded.mini, description = excluded.description,
  colors = excluded.colors, art = excluded.art, bg = excluded.bg, sort = excluded.sort, published = true, i18n = excluded.i18n, updated_at = now();
