insert into public.categories (slug, no, title, accent, blurb, care, feature_product_id, sort, i18n) values
  ('sarees', '01', 'Draped', 'Sarees', 'Six yards and more, with borders and pallus worth unfolding slowly.', 'Dry clean the first few times. Store folded in a cotton cloth and refold now and then.', 'temple-border-saree', 0, '{"te":{"title":"కట్టుకునే","accent":"చీరలు","blurb":"ఆరు గజాలకు పైగా, నెమ్మదిగా విప్పి చూడదగిన అంచులు, పల్లులతో.","care":"మొదటి కొన్నిసార్లు డ్రై క్లీన్ చేయించండి. నూలు గుడ్డలో మడిచి ఉంచి, అప్పుడప్పుడు మడత మార్చండి."},"hi":{"title":"लहराती","accent":"साड़ियाँ","blurb":"छह गज़ और उससे ज़्यादा, ऐसे किनारों और पल्लू के साथ जिन्हें धीरे-धीरे खोलकर देखने का मन करे।","care":"पहली कुछ बार ड्राई क्लीन कराएँ। सूती कपड़े में तह करके रखें और बीच-बीच में तह बदलें।"}}'::jsonb),
  ('dress-material', '02', 'Dress', 'Material', 'Unstitched sets of top, bottom and dupatta, ready for your own tailor.', 'Wash before stitching to settle the colours. Gentle hand wash in cold water.', 'block-print-set', 1, '{"te":{"title":"డ్రెస్","accent":"మెటీరియల్","blurb":"టాప్, బాటమ్, దుపట్టా — కుట్టని సెట్లు, మీ దర్జీ కోసం సిద్ధం.","care":"రంగులు నిలవడానికి కుట్టించే ముందు ఉతకండి. చల్లని నీటిలో మెల్లగా చేత్తో ఉతకండి."},"hi":{"title":"ड्रेस","accent":"मटीरियल","blurb":"टॉप, बॉटम और दुपट्टे के बिना सिले सेट, आपके अपने दर्ज़ी के लिए तैयार।","care":"रंग बैठाने के लिए सिलाई से पहले धो लें। ठंडे पानी में हल्के हाथ से धोएँ।"}}'::jsonb),
  ('coord-sets', '03', 'Co-ord', 'Sets', 'A top and bottom cut from the same cloth, made to be worn together.', 'Gentle hand wash in cold water, inside out. Dry in shade.', 'printed-coord', 2, '{"te":{"title":"కో-ఆర్డ్","accent":"సెట్లు","blurb":"ఒకే గుడ్డ నుంచి కత్తిరించిన టాప్, బాటమ్ — కలిపి వేసుకోవడానికి.","care":"లోపలి వైపు బయటకు తిప్పి చల్లని నీటిలో మెల్లగా ఉతకండి. నీడలో ఆరబెట్టండి."},"hi":{"title":"को-ऑर्ड","accent":"सेट","blurb":"एक ही कपड़े से कटे टॉप और बॉटम, साथ पहनने के लिए बने।","care":"उल्टा करके ठंडे पानी में हल्के हाथ से धोएँ। छाँव में सुखाएँ।"}}'::jsonb),
  ('gowns', '04', 'Flowing', 'Gowns', 'Floor-length flares for weddings, poojas and every evening in between.', 'Dry clean only. Hang on a padded hanger, away from direct sun.', 'anarkali-gown', 3, '{"te":{"title":"జాలువారే","accent":"గౌన్లు","blurb":"పెళ్లిళ్లకు, పూజలకు, మధ్యలో ప్రతి సాయంత్రానికీ నేల దాకా ఉండే గౌన్లు.","care":"డ్రై క్లీన్ మాత్రమే. ప్యాడెడ్ హ్యాంగర్‌పై, నేరుగా ఎండ తగలని చోట వేలాడదీయండి."},"hi":{"title":"लहराते","accent":"गाउन","blurb":"शादियों, पूजा और बीच की हर शाम के लिए ज़मीन तक घेरदार गाउन।","care":"केवल ड्राई क्लीन। गद्देदार हैंगर पर, सीधी धूप से दूर टाँगें।"}}'::jsonb),
  ('indowestern', '05', 'Indo-western', 'Jewellery', 'Light pieces that sit as well with a dress as with a kurta.', 'Plated alloy, nickel-free. Avoid perfume and water to keep the finish bright.', 'pearl-hoops', 4, '{"te":{"title":"ఇండో-వెస్టర్న్","accent":"ఆభరణాలు","blurb":"డ్రెస్‌తోనూ, కుర్తాతోనూ సమానంగా నప్పే తేలికపాటి ఆభరణాలు.","care":"ప్లేటెడ్ లోహం, నికెల్ లేనిది. మెరుపు నిలవడానికి పెర్ఫ్యూమ్, నీరు తగలనివ్వకండి."},"hi":{"title":"इंडो-वेस्टर्न","accent":"गहने","blurb":"हल्के गहने जो ड्रेस के साथ भी उतने ही जँचें जितने कुर्ते के साथ।","care":"प्लेटेड धातु, निकल-मुक्त। चमक बनाए रखने के लिए परफ़्यूम और पानी से बचाएँ।"}}'::jsonb),
  ('temple', '06', 'Temple', 'Jewellery', 'Gold-tone pieces shaped after the old temple motifs.', 'Plated alloy, nickel-free. Keep dry and store in the cloth pouch it arrives in.', 'temple-jhumka', 5, '{"te":{"title":"టెంపుల్","accent":"ఆభరణాలు","blurb":"పాత గుడి నమూనాల ఆకారంలో బంగారు రంగు ఆభరణాలు.","care":"ప్లేటెడ్ లోహం, నికెల్ లేనిది. పొడిగా ఉంచి, వచ్చిన గుడ్డ సంచిలోనే దాచండి."},"hi":{"title":"टेम्पल","accent":"गहने","blurb":"पुराने मंदिरों के रूपांकनों पर गढ़े सुनहरे रंग के गहने।","care":"प्लेटेड धातु, निकल-मुक्त। सूखा रखें और जिस कपड़े की थैली में आए उसी में रखें।"}}'::jsonb),
  ('oxidised', '07', 'Oxidised', 'Jewellery', 'Darkened silver-look metal, chased and beaded by hand.', 'Oxidised alloy, nickel-free. Keep dry and store in the cloth pouch it arrives in.', 'crescent-chandbali', 6, '{"te":{"title":"ఆక్సిడైజ్డ్","accent":"ఆభరణాలు","blurb":"ముదురు వెండి రంగు లోహం, చేత్తో చెక్కి పూసలు గుచ్చినది.","care":"ఆక్సిడైజ్డ్ లోహం, నికెల్ లేనిది. పొడిగా ఉంచి, వచ్చిన గుడ్డ సంచిలోనే దాచండి."},"hi":{"title":"ऑक्सीडाइज़्ड","accent":"गहने","blurb":"गहरी चाँदी जैसी धातु, हाथ से उकेरी और मोतियों से सजी।","care":"ऑक्सीडाइज़्ड धातु, निकल-मुक्त। सूखा रखें और जिस कपड़े की थैली में आए उसी में रखें।"}}'::jsonb),
  ('potlis', '08', 'Potli', 'Bags', 'Drawstring pouches, embroidered and beaded, to carry with festive clothes.', 'Spot clean only. Store stuffed with tissue so it keeps its shape.', 'embroidered-potli', 7, '{"te":{"title":"పొట్లీ","accent":"సంచులు","blurb":"పండుగ బట్టలతో పట్టుకెళ్లడానికి, ఎంబ్రాయిడరీ, పూసలతో తాడు సంచులు.","care":"మరకలు ఉన్న చోట మాత్రమే శుభ్రం చేయండి. ఆకారం నిలవడానికి లోపల టిష్యూ నింపి ఉంచండి."},"hi":{"title":"पोटली","accent":"बैग","blurb":"त्योहार के कपड़ों के साथ ले जाने के लिए कढ़ाई और मोतियों वाली डोरीदार पोटलियाँ।","care":"केवल दाग वाली जगह साफ़ करें। आकार बना रहे, इसलिए अंदर टिश्यू भरकर रखें।"}}'::jsonb),
  ('torans', '09', 'Doorway', 'Torans', 'Stitched bands and hand-cut flaps that dress a doorway for every arrival.', 'Cotton and thread with glass mirrors and metal bells. Dust gently; spot clean only.', 'haveli-toran', 8, '{"te":{"title":"ద్వార","accent":"తోరణాలు","blurb":"ప్రతి రాకకూ గుమ్మాన్ని అలంకరించే, చేత్తో కుట్టిన పట్టీలు, చేత్తో కత్తిరించిన రేకులు.","care":"నూలు, దారం, అద్దాలు, లోహపు గంటలతో చేసినది. మెల్లగా దుమ్ము దులపండి; మరకలు ఉన్న చోట మాత్రమే శుభ్రం చేయండి."},"hi":{"title":"द्वार","accent":"तोरण","blurb":"हाथ से सिली पट्टियाँ और हाथ से कटे पल्ले, जो हर आगमन पर दरवाज़े को सजाते हैं।","care":"सूती कपड़ा और धागा, काँच के शीशे और धातु की घंटियाँ। हल्के से धूल झाड़ें; केवल दाग वाली जगह साफ़ करें।"}}'::jsonb),
  ('bandhanwar', '10', 'Festive', 'Bandhanwar', 'Soft swags of pom-poms and tassels to hang across a door or a wall.', 'Wool, felt and cotton. Shake out gently and store flat between seasons.', 'pompom-swag', 9, '{"te":{"title":"పండుగ","accent":"బంధన్‌వార్","blurb":"గుమ్మం లేదా గోడ మీదుగా వేలాడదీయడానికి పాంపామ్‌లు, కుచ్చుల మెత్తని వంపులు.","care":"ఉన్ని, ఫెల్ట్, నూలు. మెల్లగా దులిపి, సీజన్ల మధ్య చదునుగా దాచండి."},"hi":{"title":"उत्सव","accent":"बंदनवार","blurb":"दरवाज़े या दीवार पर टाँगने के लिए पोम-पोम और फुंदनों के मुलायम झूल।","care":"ऊन, फ़ेल्ट और सूती। हल्के से झाड़ें और मौसमों के बीच समतल रखें।"}}'::jsonb)
insert into public.products (id, category_slug, name, mini, description, colors, art, bg, sort, published, i18n) values
  ('temple-border-saree', 'sarees', 'Temple Border Saree', 'Contrast border, rich pallu', 'A saree with a broad contrast border running down both sides and a pallu banded in zari-look stripes. Ask us on WhatsApp for the fabric, length and blouse piece of each colour.', array['rust','ink','earth']::text[], '{"type":"saree"}'::jsonb, '#EBD3C3', 0, true, '{"te":{"name":"టెంపుల్ అంచు చీర","mini":"విరుద్ధ రంగు అంచు, నిండైన పల్లు","description":"రెండు వైపులా వెడల్పాటి విరుద్ధ రంగు అంచు, జరీ లాంటి చారలతో పల్లు ఉన్న చీర. ప్రతి రంగు గుడ్డ, పొడవు, బ్లౌజ్ పీస్ గురించి వాట్సాప్‌లో అడగండి."},"hi":{"name":"टेम्पल बॉर्डर साड़ी","mini":"उलटे रंग का किनारा, भरा पल्लू","description":"दोनों ओर चौड़े उलटे रंग के किनारे और ज़री जैसी धारियों वाले पल्लू की साड़ी। हर रंग के कपड़े, लंबाई और ब्लाउज़ पीस के बारे में व्हाट्सऐप पर पूछें।"}}'::jsonb)
insert into public.products (id, category_slug, name, mini, description, colors, art, bg, sort, published, i18n) values
  ('block-print-set', 'dress-material', 'Block Print Dress Material', 'Top, bottom and dupatta, unstitched', 'A printed length for the top, a plain length for the bottom and a dupatta with tasselled ends, sold together and unstitched, so it can be tailored exactly to you.', array['rust','ink','natural']::text[], '{"type":"fabric"}'::jsonb, '#EFE2C9', 1, true, '{"te":{"name":"బ్లాక్ ప్రింట్ డ్రెస్ మెటీరియల్","mini":"టాప్, బాటమ్, దుపట్టా — కుట్టనిది","description":"టాప్ కోసం ప్రింట్ గుడ్డ, బాటమ్ కోసం సాదా గుడ్డ, కుచ్చుల అంచుల దుపట్టా — కుట్టకుండా కలిపి అమ్ముతాం, మీ కొలతలకు సరిగ్గా కుట్టించుకోవచ్చు."},"hi":{"name":"ब्लॉक प्रिंट ड्रेस मटीरियल","mini":"टॉप, बॉटम और दुपट्टा, बिना सिला","description":"टॉप के लिए छपा कपड़ा, बॉटम के लिए सादा कपड़ा और फुंदनों वाले किनारों का दुपट्टा, बिना सिले एक साथ, ताकि आप ठीक अपने नाप से सिलवा सकें।"}}'::jsonb)
insert into public.products (id, category_slug, name, mini, description, colors, art, bg, sort, published, i18n) values
  ('printed-coord', 'coord-sets', 'Printed Co-ord Set', 'Easy top with straight pants', 'A relaxed top and straight pants cut from the same printed cloth, with contrast bands at the hems. Wear them together, or apart with what you already have.', array['earth','rust','ink']::text[], '{"type":"coord"}'::jsonb, '#E4D9C6', 2, true, '{"te":{"name":"ప్రింటెడ్ కో-ఆర్డ్ సెట్","mini":"సౌకర్యమైన టాప్, స్ట్రెయిట్ ప్యాంట్","description":"ఒకే ప్రింట్ గుడ్డ నుంచి కత్తిరించిన వదులైన టాప్, స్ట్రెయిట్ ప్యాంట్, అంచుల వద్ద విరుద్ధ రంగు పట్టీలతో. కలిపి వేసుకోండి, లేదా మీ దగ్గర ఉన్నవాటితో విడిగా."},"hi":{"name":"प्रिंटेड को-ऑर्ड सेट","mini":"आरामदायक टॉप, सीधी पैंट","description":"एक ही छपे कपड़े से कटे ढीले टॉप और सीधी पैंट, किनारों पर उलटे रंग की पट्टियों के साथ। साथ पहनें, या अलग-अलग अपने कपड़ों के साथ।"}}'::jsonb)
insert into public.products (id, category_slug, name, mini, description, colors, art, bg, sort, published, i18n) values
  ('anarkali-gown', 'gowns', 'Flared Anarkali Gown', 'Floor-length, full flare', 'A fitted bodice opening into a deep, many-panelled flare, finished with a heavy border at the hem. Ask us on WhatsApp for sizes and fabric.', array['ink','rust','earth']::text[], '{"type":"gown"}'::jsonb, '#E6D5B4', 3, true, '{"te":{"name":"ఫ్లేర్డ్ అనార్కలీ గౌన్","mini":"నేల దాకా, నిండు కుచ్చిళ్లు","description":"బిగుతైన పైభాగం నుంచి అనేక కలీలతో విచ్చుకునే లోతైన కుచ్చిళ్లు, కింద బరువైన అంచు. సైజులు, గుడ్డ గురించి వాట్సాప్‌లో అడగండి."},"hi":{"name":"घेरदार अनारकली गाउन","mini":"ज़मीन तक, पूरा घेर","description":"कसी हुई चोली से खुलता कई कलियों वाला गहरा घेर, नीचे भारी किनारे के साथ। साइज़ और कपड़े के बारे में व्हाट्सऐप पर पूछें।"}}'::jsonb)
insert into public.products (id, category_slug, name, mini, description, colors, art, bg, sort, published, i18n) values
  ('pearl-hoops', 'indowestern', 'Pearl Fringe Hoops', 'Hoops dressed in seed pearls', 'Light hoops with a fringe of seed pearls that moves when you do. Easy with a dress, a kurta or a saree.', array['gold-pearl','silver-pearl','gold','silver']::text[], '{"type":"hoops","fringe":true}'::jsonb, '#EBD3C3', 4, true, '{"te":{"name":"ముత్యాల కుచ్చు హూప్స్","mini":"సన్న ముత్యాలతో అలంకరించిన హూప్స్","description":"మీరు కదిలినప్పుడు కదిలే సన్న ముత్యాల కుచ్చుతో తేలికపాటి హూప్స్. డ్రెస్, కుర్తా, చీర — దేనితోనైనా నప్పుతాయి."},"hi":{"name":"मोती झालर हूप्स","mini":"छोटे मोतियों से सजे हूप्स","description":"हल्के हूप्स, जिनकी छोटे मोतियों की झालर आपके साथ हिलती है। ड्रेस, कुर्ते या साड़ी, किसी के भी साथ आसान।"}}'::jsonb)
insert into public.products (id, category_slug, name, mini, description, colors, art, bg, sort, published, i18n) values
  ('temple-jhumka', 'temple', 'Temple Jhumka', 'Domed bells, beaded fringe', 'Domed jhumkas in a warm gold tone, with a fringe of beads below, after the jewellery carved on temple walls.', array['gold','gold-pearl']::text[], '{"type":"jhumka"}'::jsonb, '#E6D5B4', 5, true, '{"te":{"name":"టెంపుల్ జుంకా","mini":"గోపురం లాంటి గంటలు, పూసల కుచ్చు","description":"గుడి గోడలపై చెక్కిన ఆభరణాల స్ఫూర్తితో, కింద పూసల కుచ్చుతో, వెచ్చని బంగారు రంగు గోపురం జుంకాలు."},"hi":{"name":"टेम्पल झुमका","mini":"गुंबद जैसी घंटियाँ, मोतियों की झालर","description":"मंदिर की दीवारों पर उकेरे गहनों से प्रेरित, नीचे मोतियों की झालर वाले गर्म सुनहरे रंग के गुंबददार झुमके।"}}'::jsonb)
insert into public.products (id, category_slug, name, mini, description, colors, art, bg, sort, published, i18n) values
  ('crescent-chandbali', 'oxidised', 'Crescent Chandbali', 'Moon-shaped, pearl-edged drops', 'Crescent-moon chandbalis in darkened silver-look metal, edged with small pearls. Light for their size, so you can wear them all evening.', array['oxidised-pearl','oxidised']::text[], '{"type":"chandbali"}'::jsonb, '#E4D9C6', 6, true, '{"te":{"name":"అర్ధచంద్ర చాంద్‌బాలీ","mini":"చంద్రవంక ఆకారం, ముత్యాల అంచు","description":"చిన్న ముత్యాల అంచుతో, ముదురు వెండి రంగు లోహంలో అర్ధచంద్రాకార చాంద్‌బాలీలు. పరిమాణానికి తగ్గట్టు తేలికగా ఉంటాయి, సాయంత్రమంతా వేసుకోవచ్చు."},"hi":{"name":"अर्धचंद्र चांदबाली","mini":"चाँद के आकार की, मोतियों की किनारी","description":"छोटे मोतियों की किनारी वाली, गहरी चाँदी जैसी धातु में अर्धचंद्र चांदबालियाँ। आकार के हिसाब से हल्की, पूरी शाम पहन सकें।"}}'::jsonb)
insert into public.products (id, category_slug, name, mini, description, colors, art, bg, sort, published, i18n) values
  ('embroidered-potli', 'potlis', 'Embroidered Potli Bag', 'Drawstring pouch, beaded hem', 'A gathered drawstring potli with an embroidered flower on the front, a beaded edge and tasselled strings. Big enough for a phone, keys and a little more.', array['rust','ink','natural']::text[], '{"type":"potli"}'::jsonb, '#DCC8A5', 7, true, '{"te":{"name":"ఎంబ్రాయిడరీ పొట్లీ సంచి","mini":"తాడు సంచి, పూసల అంచు","description":"ముందు ఎంబ్రాయిడరీ పువ్వు, పూసల అంచు, కుచ్చుల తాళ్లతో ముడుచుకునే పొట్లీ. ఫోన్, తాళాలు, ఇంకొంచెం పట్టేంత పెద్దది."},"hi":{"name":"कढ़ाईदार पोटली बैग","mini":"डोरी वाली थैली, मोतियों का किनारा","description":"सामने कढ़ाई वाला फूल, मोतियों का किनारा और फुंदनों वाली डोरियों के साथ सिकुड़ने वाली पोटली। फ़ोन, चाबियाँ और थोड़ा और समा जाए इतनी बड़ी।"}}'::jsonb)
insert into public.products (id, category_slug, name, mini, description, colors, art, bg, sort, published) values
  ('haveli-toran', 'torans', 'Haveli Doorway Toran', 'Seven flaps, mirror-stitched band', 'A cotton band edged in running stitch, set with tiny mirrors, and hung with seven pointed flaps. Each flap ends in a small brass-tone bell, so the doorway answers softly when someone walks through.', array['rust','ink','earth','natural']::text[], '{"type":"toran","flaps":7,"shape":"tri","bells":true}'::jsonb, '#EFE2C9', 8, true)
insert into public.products (id, category_slug, name, mini, description, colors, art, bg, sort, published) values
  ('pompom-swag', 'bandhanwar', 'Pom-pom Swag Garland', 'Woolly pom-poms, three swags', 'Three soft swags of hand-wound wool pom-poms, with tassels at every join. Drape it over a doorway, a mantel or a window.', array['rust','ink','earth','natural']::text[], '{"type":"garland","style":"pompom","swags":3}'::jsonb, '#EFE2C9', 9, true)
